// src/useAuth.js
import { useState, useEffect, createContext, useContext } from 'react';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [auth, setAuth] = useState(false);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true); // To handle initial loading state

  useEffect(() => {
    const token = localStorage.getItem('authToken');

    if (token) {
      // Simulate token verification and user data fetching
      let simulatedUser = null;
      if (token === 'fakeRestaurantToken') {
        simulatedUser = { id: 'resId', username: 'restaurant', role: 'restaurant' };
      } else if (token === 'fakeCustomerToken') {
        simulatedUser = { id: 'custId', username: 'customer', role: 'customer' };
      } else if (token === 'fakeAdminToken') {
        simulatedUser = { id: 'adminId', username: 'admin', role: 'admin' };
      }

      if (simulatedUser) {
        setAuth(true);
        setUser(simulatedUser);
      } else {
        setAuth(false);
        setUser(null);
      }
    } else {
      setAuth(false);
      setUser(null);
    }
    setLoading(false);
  }, []);

  const login = async (credentials) => {
    setLoading(true);
    // **Replace the simulation with your actual login API call.**
    if (credentials.username === 'restaurant' && credentials.password === 'password') {
      const simulatedRestaurantUser = { id: 'resId', username: 'restaurant', role: 'restaurant' };
      localStorage.setItem('authToken', 'fakeRestaurantToken');
      setUser(simulatedRestaurantUser);
      setAuth(true);
      setLoading(false);
      return true;
    } else if (credentials.username === 'customer' && credentials.password === 'password') {
      const simulatedCustomerUser = { id: 'custId', username: 'customer', role: 'customer' };
      localStorage.setItem('authToken', 'fakeCustomerToken');
      setUser(simulatedCustomerUser);
      setAuth(true);
      setLoading(false);
      return true;
    } else if (credentials.username === 'admin' && credentials.password === 'password') {
      const simulatedAdminUser = { id: 'adminId', username: 'admin', role: 'admin' };
      localStorage.setItem('authToken', 'fakeAdminToken');
      setUser(simulatedAdminUser);
      setAuth(true);
      setLoading(false);
      return true;
    } else {
      setAuth(false);
      setUser(null);
      setLoading(false);
      return false;
    }
  };

  const logout = () => {
    localStorage.removeItem('authToken');
    setAuth(false);
    setUser(null);
  };

  const value = { auth, user, login, logout, loading };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  return useContext(AuthContext);
};
